import ipaddress

def sg_allows(rules, protocol, port, source):
    """Inbound check for a security group. rules is a list of dicts like
    {"protocol": "tcp", "ports": (443, 443), "source": "0.0.0.0/0"}; protocol may be
    "tcp", "udp" or "all" ("all" matches any protocol and port). Return True if the packet
    (protocol, destination port, source address) matches at least one rule."""
    src = ipaddress.ip_address(source)
    for rule in rules:
        if rule["protocol"] not in ("all", protocol):
            continue
        lo, hi = rule["ports"]
        if rule["protocol"] != "all" and not lo <= port <= hi:
            continue
        if src in ipaddress.ip_network(rule["source"]):
            return True
    return False

exercises.solution:
Loop over the rules and return `True` at the first one whose protocol, port range and source all match; if none does, the default is to deny:

```python
import ipaddress

def sg_allows(rules, protocol, port, source):
    src = ipaddress.ip_address(source)
    for rule in rules:
        if rule["protocol"] not in ("all", protocol):
            continue
        lo, hi = rule["ports"]
        if rule["protocol"] != "all" and not lo <= port <= hi:
            continue
        if src in ipaddress.ip_network(rule["source"]):
            return True
    return False
```

Because security-group rules only *allow*, their order does not matter: the packet is allowed if any rule matches. (Ordered rule lists with explicit denies, such as network ACLs or priority-ordered firewall rules, need the first matching rule instead.) Real implementations compile the rules into lookup structures rather than scanning them, and track connections so that replies are allowed — the *stateful* part.
